const out = { internal: require('#internal'), cond: require('#cond'), dir: require('#dir/x'), dep: require('#dep') };
for (const spec of ['#nope', '#missing', '#bad', '#', '#/x']) {
  try { require(spec); } catch (e) { out[spec] = [e.code, e.message.split(__dirname).join('<imp>')]; }
}
module.exports = out;
